#!/usr/bin/env python3
import sys
from fractions import Fraction

MIN_EXP = -348
MAX_EXP = 347

MASK64 = (1 << 64) - 1
B1P64 = 1 << 64
B1P128 = 1 << 128
R1P128 = Fraction(B1P128, 1)

TOP = """\
// Derived from Russ Cox's fpfmt (BSD-3-Clause). See LICENSE.md.

// Code generated by: gen_pow_table.py. DO NOT EDIT.
//
// Ported from the Go standard library's pow10gen.go (BSD-style license).
// Produces the same 128-bit power-of-10 mantissa table, computed with
// exact rational arithmetic (Python's fractions.Fraction in place of
// Go's math/big.Rat).
#ifndef POW10_HPP
#define POW10_HPP

#include <cstdint>

enum {{
\tpow10Min = {min_exp},
\tpow10Max = {max_exp},
}};

[[maybe_unused]] static uint64_t uint64pow10[] = {{
\t{uint64pow10_entries}
}};

// pow10Tab holds 128-bit mantissas of powers of 10.
// The values are scaled so the high bit is always set.
[[maybe_unused]] static uint64_t pow10Tab[pow10Max-pow10Min+1][2] = {{
"""

BOTTOM = """\
};

#endif
"""

def u64(x: int) -> int:
	return x & MASK64

def gen_uint64pow10(n: int = 20):
	return [10 ** i for i in range(n)]

def gen_pow10_row(e: int):
	if e >= 0:
		r = Fraction(10 ** e, 1)
	else:
		r = Fraction(1, 10 ** (-e))

	be = 0
	while r < R1P128:
		r *= 2
		be += 1
	while r >= R1P128:
		r /= 2
		be -= 1

	d = r.numerator // r.denominator
	is_exact = (r.denominator == 1)

	hi, lo = divmod(d, B1P64)
	uhi = u64(hi)
	ulo = u64(lo)

	if not is_exact:
		ulo = u64(ulo + 1)
		if ulo == 0:
			uhi = u64(uhi + 1)

	if ulo != 0:
		uhi = u64(uhi + 1)
		ulo = u64(-ulo)

	return uhi, ulo, be

def generate(min_exp: int = MIN_EXP, max_exp: int = MAX_EXP):
	rows = []
	for e in range(min_exp, max_exp + 1):
		uhi, ulo, be = gen_pow10_row(e)
		rows.append((uhi, ulo, e, be))
	return rows

def format_uint64pow10(values):
	return ", ".join(f"{v}ULL" for v in values)

def render(min_exp: int = MIN_EXP, max_exp: int = MAX_EXP) -> str:
	rows = generate(min_exp, max_exp)
	uint64pow10_entries = format_uint64pow10(gen_uint64pow10(20))

	lines = []
	for uhi, ulo, e, be in rows:
		lines.append(f"\t{{0x{uhi:016x}, 0x{ulo:016x}}}, // 1e{e} * 2**{be}")

	out = TOP.format(
		min_exp=min_exp,
		max_exp=max_exp,
		uint64pow10_entries=uint64pow10_entries,
	)
	out += "\n".join(lines) + "\n"
	out += BOTTOM
	return out

def main():
	out_path = sys.argv[1] if len(sys.argv) > 1 else "pow10.hpp"
	text = render()
	with open(out_path, "w") as f:
		f.write(text)
	print(f"wrote {out_path}")

if __name__ == "__main__":
	main()